B.aVF=new A.ex(!0,"Sheet hung. Now screw it to the studs.",!1,"")
B.aVG=new A.ex(!0,"Hole drilled through the middle of the stud, at the cable height. Holes go in the center so a nail cannot reach the cable.",!1,"")
B.aVH=new A.ex(!0,"Plugged in. Nothing happens because the breaker is off. Turn it on to test.",!1,"")
B.aVI=new A.ex(!0,"You flipped the tripped breaker fully OFF. Fix the problem before you turn it on again.",!1,"")
B.aVJ=new A.ex(!0,"Click.",!1,"")
B.aVK=new A.ex(!0,"The wires are folded back and the device is in the box. Now put the cover on.",!1,"")
B.aVL=new A.ex(!0,"Breaker OFF. The wires on this circuit are dead now. (Always test them to be sure.)",!1,"")
B.aVM=new A.ex(!1,"Nothing is wet.",!1,"")
B.aVN=new A.ex(!0,"Power is on.",!1,"")
B.aVO=new A.ex(!0,"Water OFF at the main valve. You can cut into the pipes safely now.",!1,"")
B.aVP=new A.ex(!0,"Opening cut around the box with the drywall saw. Keep it tight: the plate has to cover the edge.",!1,"")
B.aVQ=new A.ex(!0,"Device pulled out of the box.",!1,"")
B.aVR=new A.ex(!0,"Screw set just below the paper, not through it.",!1,"")
B.aVS=new A.ex(!1,"ZAP! You touched a live wire. In Learn mode you are not hurt, but in real life this can kill. Switch the breaker OFF and test the wires first.",!0,"shock")
