B.bTC=new A.jA("Breaker off, then test","Before you touch any wire, switch its breaker OFF, then check with a voltage tester that the wire is dead. A switch on the wall is not enough.")
B.bTp=new A.jA("Lock out, tag out","On a real job you put a lock or a note on the panel so nobody switches the power back on while you work.")
B.bTJ=new A.jA("Water and power","Water carries electricity. Near sinks, tubs and outdoors the outlets must be GFCI, and wet hands never touch wires.")
B.bTu=new A.jA("Eyes, ears, lungs","Safety glasses for drilling and cutting, ear protection for loud tools, and a mask when you sand drywall dust or cut tile.")
B.bTI=new A.jA("Shut the water off","Before you cut or loosen a pipe, close the main water valve and open a faucet to drain the line.")
B.d9l=w([B.bTC,B.bTp,B.bTJ,B.bTu,B.bTI],x.Z)
B.bTV=new A.Mq("Safety first","\ud83e\uddba",D.ca,B.d9l)
B.bTK=new A.jA("Wire colours","Black is hot (it carries the power), white is neutral (the way back), bare copper or green is ground (the safety path). Red is a second hot, often used for a switched line.")
B.bTR=new A.jA("Screw colours","On an outlet the brass screw takes the hot wire, the silver screw takes the neutral and the green screw takes the ground.")
B.bTE=new A.jA("Wire size","14 gauge wire is for 15 amp circuits (lights and outlets). 12 gauge is for 20 amp circuits (kitchens). A thinner wire than the breaker allows can overheat and start a fire.")
B.bTy=new A.jA("Breakers","A breaker is a safety switch. It trips when a circuit carries too much current, so the wires never get hot enough to burn.")
B.bTM=new A.jA("Wire nuts","Strip about 3/4 inch, twist the bare ends together clockwise, and screw on the nut until no bare copper shows. Give each wire a gentle tug.")
B.bTS=new A.jA("Switches","A switch cuts the hot wire only. The neutral goes straight through to the light.")
B.bTT=new A.jA("GFCI","A GFCI outlet watches the current going out and coming back. If a little leaks (through water or a person) it cuts the power in a fraction of a second.")
B.bTr=new A.jA("Ceiling fans","A fan shakes and is heavy. It needs a box that says fan rated, fixed to the joist, not a plain light box.")
B.bTt=new A.jA("Heights","Outlets sit about 16 inches from the floor. Switches sit about 48 inches up, where your hand falls.")
B.d23=w([B.bTK,B.bTR,B.bTE,B.bTy,B.bTM,B.bTS,B.bTT,B.bTr,B.bTt],x.Z)
B.bTY=new A.Mq("Wiring basics","\u26a1",D.bZ,B.d23)
B.bTq=new A.jA("Hot left, cold right","On a faucet, hot is on the left and cold on the right. Hot lines are marked red and cold lines blue.")
B.bTD=new A.jA("The P-trap","The curved pipe under a sink always holds a little water. That water seal stops sewer gas coming up the drain.")
B.bTO=new A.jA("Shut-off valves","Every sink and toilet has its own small valve, so you can stop the water to one fixture without turning off the whole house.")
B.bTw=new A.jA("Slip nuts","Drain joints are sealed by a washer and a slip nut. Tighten by hand and a quarter turn: too much force cracks plastic.")
B.bTv=new A.jA("Wax ring","A toilet sits on a wax ring that seals it to the floor drain. A toilet is lowered straight down once, and cannot be slid around.")
B.bTL=new A.jA("Drain slope","Drains fall about 1/4 inch per foot so water and waste keep moving. Too flat and it clogs, too steep and the water leaves the solids behind.")
B.bTQ=new A.jA("Order of work","Plumbing goes from the top down on the drain (tailpiece, trap, arm) and from the wall out on the supply (valve, hose, fixture).")
B.cay=w([B.bTq,B.bTD,B.bTO,B.bTw,B.bTv,B.bTL,B.bTQ],x.Z)
B.bTW=new A.Mq("Plumbing basics","\ud83d\udeb0",D.co,B.cay)
B.bTs=new A.jA("Studs","Studs are the vertical 2x4 posts inside a wall, 16 inches apart from centre to centre. Everything is fixed to them.")
B.bTG=new A.jA("Drilling studs","Holes for cable go through the middle of the stud, so a nail or screw cannot reach the wire.")
B.bTx=new A.jA("Drywall","A sheet is 4 feet wide, so its edges land on studs 48 inches apart. Screws go into studs only, just under the paper.")
B.bTA=new A.jA("Taping and mud","Seams get paper tape and three thin coats of joint compound, sanded smooth between coats, then primer and paint.")
B.bTP=new A.jA("Order of a build","Frame, run the pipes and wires (rough-in), inspect, hang drywall, finish it, paint, then fit the fixtures and devices.")
B.cOL=w([B.bTs,B.bTG,B.bTx,B.bTA,B.bTP],x.Z)
B.bTU=new A.Mq("Framing and walls","\ud83c\udfe0",D.dU,B.cOL)
B.bTB=new A.jA("Voltage tester","A pen that glows or beeps near live wires. Test it on a known live outlet first, so you know it works.")
B.bTH=new A.jA("Wire strippers","Strip the plastic off without nicking the copper. A nick weakens the wire.")
B.bTN=new A.jA("Adjustable wrench","For nuts on valves and hoses. Hold the fitting steady with a second wrench so you do not twist the pipe.")
B.bTF=new A.jA("Drill and screw gun","A drill makes holes through studs. A screw gun sets drywall screws to the right depth.")
B.bTz=new A.jA("Level and tape measure","Measure twice, cut once. A level makes sure outlets, shelves and pipes are straight.")
B.dh8=w([B.bTB,B.bTH,B.bTN,B.bTF,B.bTz],x.Z)
B.bTX=new A.Mq("Tools","\ud83e\uddf0",D.bv,B.dh8)
